// Ciclo for per processare tutti i PDF inviati
// In n8n i dati viaggiano in array (liste), quindi $input.all() garantisce che non vengano persi file
for (let item of $input.all()) {

  // Si prende il testo originale e se ne fa una copia in maiuscolo per la ricerca
  let testoOriginale = item.json.text || "";
  let textUpper = testoOriginale.toUpperCase();

  // Si cerca l'inizio: cerca "ART. 1"
  let start = textUpper.indexOf("\nART. 1");
  if (start === -1) {
    start = textUpper.indexOf("ART. 1"); 
  }
  if (start === -1) {
    start = 0; // Se non c'è, parti dall'inizio
  }

  // Crova la fine: fermati all'Art. 6 (o 7)
  let end = textUpper.indexOf("\nART. 6");
  if (end === -1) {
    end = textUpper.indexOf("\nART. 7");
  }

  // Se il bando è corto e non c'è l'Art 6,si prendono circa 6000 caratteri
  if (end === -1 || end < start) {
    end = start + 6000;
  }

  // Si taglia il testo ORIGINALE così ceh flowise vada a leggere il contenuto di partenza
  let contenuto = testoOriginale.substring(start, end);

  // Inserimento nella variabile "question" per flowise
  item.json.question = contenuto;

}

// Restituisci la lista modificata
return $input.all();

parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "titolo": {
      "type": "string",
      "description": "Il titolo principale formale del documento, estratto letteralmente dalle primissime righe in cima al testo (es. BANDO DI SELEZIONE, AVVISO DI VACANZA, ecc.), unendo le righe in una sola stringa senza ritorni a capo."
    },
    "scadenza": {
      "type": "string",
      "description": "La data e l'ora di scadenza del bando nel formato GG/MM/AAAA ore HH:MM. Se l'orario non è specificato nel documento, indicare solo la data GG/MM/AAAA."
    },
    "requisiti": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Lista dei soli requisiti obbligatori di ammissione elencati con lettere a), b), c)... nell'articolo sui requisiti. Ogni requisito è un elemento separato. Massimo 10 voci, sintetizzate in frasi brevi mantenendo la punteggiatura originale."
    },
    "gia_presente": {
      "type": "boolean",
      "description": "true se il tool MongoDB ha trovato un documento corrispondente, false se non ha trovato nulla."
    }
  },
  "required": ["titolo", "scadenza", "requisiti", "gia_presente"]
}
